-- 0019 part 1 of 4: Balanced nutrition plans. Run the parts in order (part 1 adds the new foods).
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Soya yoghurt, plain', null, 50, 4.0, 2.1, 2.3, 1.0, null, null, 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Soya yoghurt, plain'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Soya milk, unsweetened', null, 33, 3.0, 0.0, 1.8, 0.6, 250, '1 glass', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Soya milk, unsweetened'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Edamame beans, frozen', null, 121, 11.9, 8.9, 5.2, 5.2, 80, '1 handful', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Edamame beans, frozen'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Per4m Advanced Whey Protein', 'Per4m', 350, 73.3, 10.0, 2.7, 1.0, 30, '1 scoop', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Per4m Advanced Whey Protein'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Per4m Isolate Zero', 'Per4m', 362, 85.0, 1.5, 1.3, 1.5, 30, '1 scoop', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Per4m Isolate Zero'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Per4m Plant Protein', 'Per4m', 404, 70.0, 4.0, 8.5, 5.4, 30, '1 scoop', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Per4m Plant Protein'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Per4m Protein Bar', 'Per4m', 326, 32.0, 39.0, 8.6, 8.3, 62, '1 bar', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Per4m Protein Bar'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Strom NiHPRO Protein Isolate', 'Strom', 377, 73.3, 11.0, 5.3, 0.0, 30, '1 scoop', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Strom NiHPRO Protein Isolate'));
insert into public.foods (name, brand, kcal, protein_g, carbs_g, fat_g, fibre_g, serving_g, serving_name, source)
select 'Strom Cream of Rice', 'Strom', 327, 6.6, 72.0, 1.0, 3.0, 25, '1 scoop', 'coach'
where not exists (select 1 from public.foods where owner_id is null and lower(name) = lower('Strom Cream of Rice'));

-- Balanced: 14 plans, 1,400 to 4,000 kcal.
delete from public.templates where kind = 'nutrition' and name like 'Balanced, %kcal';
insert into public.templates (kind, name, summary, goal, level, audience, competitor, tags, body)
select 'nutrition', v.name, v.summary, v.goal, 'Beginner', 'any', 'any', v.tags::text[], v.body
from (values
('Balanced, 1,400 kcal', '1,400 kcal (5,858 kJ). Everyday foods, about 30% protein, carbs around training. Training and rest days, 3 meals and a snack.', 'General health', '{"balanced","trial","1400 kcal"}', $${"style":"plan","notes":"Eat roughly the same each day and don't stress about being exact. Hit your protein first. Training days swap the afternoon snack for a post-workout meal with more carbs. Weigh your food for the first week or two if you can, then hand portions are fine. Fill up on veg as much as you like.","day_types":[{"name":"Training day","weekdays":[1,2,4,5],"kcal":1400,"protein_g":116,"carbs_g":149,"fat_g":37,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":5,"fists":4,"cupped":5,"thumbs":4,"notes":"Post-workout meal within an hour or so of training.","meals":[{"name":"Breakfast","notes":"Swap: 2 eggs on 2 slices of wholemeal toast instead of the oats and yoghurt, or skyr for the yoghurt.","items":[{"food":"Oats, rolled","grams":45},{"food":"Milk, semi-skimmed / light blue","grams":120},{"food":"Greek yoghurt, 0% fat","grams":130},{"food":"Frozen mixed berries","grams":60}]},{"name":"Lunch","notes":"Swap: turkey mince, tuna or prawns for the chicken; a wrap or a microwave rice pouch for the rice.","items":[{"food":"Chicken breast, grilled","grams":110},{"food":"Basmati rice, cooked","grams":120},{"food":"Mixed salad leaves","grams":45},{"food":"Tomato","grams":70},{"food":"Avocado","grams":30}]},{"name":"Post-workout","notes":"Within an hour or so of training. Swap: Per4m Isolate Zero or Strom NiHPRO for the whey; oats or rice cakes for the cream of rice.","items":[{"food":"Per4m Advanced Whey Protein","grams":25},{"food":"Strom Cream of Rice","grams":25},{"food":"Banana","grams":60}]},{"name":"Dinner","notes":"Swap: cod, lean beef mince or chicken thigh for the salmon; sweet potato, pasta or rice for the potatoes; any veg.","items":[{"food":"Salmon fillet, raw","grams":120},{"food":"Potato, raw","grams":150},{"food":"Broccoli","grams":85},{"food":"Green beans","grams":70},{"food":"Olive oil","grams":5}]}]},{"name":"Rest day","weekdays":[3,6,7],"kcal":1400,"protein_g":113,"carbs_g":139,"fat_g":42,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":5,"fists":4,"cupped":5,"thumbs":4,"notes":null,"meals":[{"name":"Breakfast","notes":"Swap: 2 eggs on 2 slices of wholemeal toast instead of the oats and yoghurt, or skyr for the yoghurt.","items":[{"food":"Oats, rolled","grams":50},{"food":"Milk, semi-skimmed / light blue","grams":120},{"food":"Greek yoghurt, 0% fat","grams":130},{"food":"Frozen mixed berries","grams":60}]},{"name":"Lunch","notes":"Swap: turkey mince, tuna or prawns for the chicken; a wrap or a microwave rice pouch for the rice.","items":[{"food":"Chicken breast, grilled","grams":110},{"food":"Basmati rice, cooked","grams":120},{"food":"Mixed salad leaves","grams":45},{"food":"Tomato","grams":70},{"food":"Avocado","grams":30}]},{"name":"Snack","notes":"Swap: cottage cheese for the skyr, any fruit for the banana, or a Per4m Protein Bar on busy days.","items":[{"food":"Skyr, plain","grams":130},{"food":"Banana","grams":70},{"food":"Almonds","grams":10}]},{"name":"Dinner","notes":"Swap: cod, lean beef mince or chicken thigh for the salmon; sweet potato, pasta or rice for the potatoes; any veg.","items":[{"food":"Salmon fillet, raw","grams":120},{"food":"Potato, raw","grams":150},{"food":"Broccoli","grams":85},{"food":"Green beans","grams":70},{"food":"Olive oil","grams":5}]}]}]}$$::jsonb),
